from __future__ import annotations

DEFAULT_PORT = 8080
MINIMUM_PORT = 1
MAXIMUM_PORT = 65_535


class PortBounds:
    def __init__(self, minimum: int, maximum: int) -> None:
        self.minimum = minimum
        self.maximum = maximum

    def clamp(self, value: int) -> int:
        if value < self.minimum:
            return self.minimum
        if value > self.maximum:
            return self.maximum
        return value


class PortParser:
    def parse(self, value: str | None) -> int:
        if value is None:
            return DEFAULT_PORT
        return int(value)


class PortResolver:
    def __init__(self, parser: PortParser, bounds: PortBounds) -> None:
        self.parser = parser
        self.bounds = bounds

    def resolve(self, value: str | None) -> int:
        parsed = self.parser.parse(value)
        return self.bounds.clamp(parsed)


_resolver = PortResolver(PortParser(), PortBounds(MINIMUM_PORT, MAXIMUM_PORT))


def resolve_port(value: str | None) -> int:
    return _resolver.resolve(value)

